<?php
namespace Tests\Feature;
use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class CompanyProfileTest extends TestCase{use RefreshDatabase;public function test_representative_can_create_and_update_company_profile():void{$user=User::factory()->create(['account_type'=>'company','name'=>'Responsable Acme']);$this->actingAs($user,'sanctum')->getJson('/api/v1/company/profile')->assertOk()->assertJsonPath('data.member_role','owner');$this->actingAs($user,'sanctum')->putJson('/api/v1/company/profile',['name'=>'Acme SRL','legal_name'=>'Acme Dominicana SRL','tax_id'=>'131000001','description'=>'Empresa de tecnología con operaciones nacionales.','industry'=>'Tecnología','location'=>'Santo Domingo','phone'=>'8095550101','size'=>'11-50','website'=>'https://example.com'])->assertOk()->assertJsonPath('data.completion',100);$this->actingAs($user,'sanctum')->postJson('/api/v1/company/verification/submit')->assertOk()->assertJsonPath('data.verification_status','pending');}public function test_incomplete_company_cannot_submit_verification():void{$user=User::factory()->create(['account_type'=>'company']);$this->actingAs($user,'sanctum')->getJson('/api/v1/company/profile');$this->actingAs($user,'sanctum')->postJson('/api/v1/company/verification/submit')->assertUnprocessable();}public function test_candidate_cannot_access_company_profile():void{$user=User::factory()->create(['account_type'=>'candidate']);$this->actingAs($user,'sanctum')->getJson('/api/v1/company/profile')->assertForbidden();}}
